/* eslint-disable */
// @ts-nocheck
/* Generated by scripts/sync-book.mjs from the brand book. Do not edit. */
/* ClimbUK brand centre: the interactive parts. Plain script, no framework, no network calls beyond this site's own
   files. Every control works with a keyboard, and anything that moves respects reduced motion. */
export function initBrandBook(hooks) {
    "use strict";

    var book = document.getElementById("cbb");
    if (!book) {
        return;
    }
    var THEMES = ["dark", "light", "aaa-dark", "aaa-light"];
    var reduced = window.matchMedia("(prefers-reduced-motion: reduce)");

    function $(sel, root) { return (root || document).querySelector(sel); }
    function $$(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
    function store(key, value) {
        try {
            if (value === undefined) {
                return window.localStorage.getItem(key);
            }
            window.localStorage.setItem(key, value);
        } catch (e) { /* private mode: the choice lasts for this page only */ }
        return null;
    }
    function esc(s) {
        return String(s).replace(/[&<>"]/g, function (c) {
            return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
        });
    }

    // ---------------------------------------------------------------- toast and copy

    var toast = $("[data-cbb-toast]", book);
    var toastTimer;
    function say(text) {
        if (!toast) {
            return;
        }
        toast.textContent = text;
        toast.classList.add("is-on");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(function () { toast.classList.remove("is-on"); }, 2200);
    }
    function copy(text, label) {
        function done() { say("Copied " + label); }
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(done, fallback);
        } else {
            fallback();
        }
        function fallback() {
            var t = document.createElement("textarea");
            t.value = text;
            t.setAttribute("readonly", "");
            t.style.position = "fixed";
            t.style.opacity = "0";
            document.body.appendChild(t);
            t.select();
            try {
                document.execCommand("copy");
                done();
            } catch (e) {
                say("Select and copy: " + text.slice(0, 40));
            }
            t.remove();
        }
    }

    // ---------------------------------------------------------------- contrast maths

    function lum(hex) {
        var c = hex.replace("#", "");
        return [0, 2, 4].map(function (i) {
            var v = parseInt(c.substr(i, 2), 16) / 255;
            return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
        }).reduce(function (a, v, i) { return a + v * [0.2126, 0.7152, 0.0722][i]; }, 0);
    }
    function ratio(a, b) {
        var x = lum(a), y = lum(b);
        return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
    }

    // ---------------------------------------------------------------- theme and size

    var frames = [];
    function currentTheme() { return book.getAttribute("data-climb-theme"); }
    function setTheme(theme, quiet) {
        if (THEMES.indexOf(theme) < 0) {
            theme = "dark";
        }
        book.setAttribute("data-climb-theme", theme);
        store("cbb-theme", theme);
        $$("[data-cbb-theme-select]").forEach(function (s) { s.value = theme; });
        $$("[data-cbb-theme-col]").forEach(function (c) {
            c.classList.toggle("is-current", c.getAttribute("data-cbb-theme-col") === theme);
        });
        frames.forEach(function (f) { f.theme(); });
        $$("[data-cbb-logo]").forEach(function (img) {
            var want = /light$/.test(theme) ? "_full-colour-light.svg" : "_reversed-dark.svg";
            img.src = img.src.replace(/_(reversed-dark|full-colour-light)\.svg$/, want);
        });
        if (!quiet) {
            say("Theme: " + theme.replace("aaa-", "AAA ").replace(/^\w/, function (c) { return c.toUpperCase(); }));
        }
    }
    function setSize(size) {
        if (size === "aaa") {
            book.setAttribute("data-climb-size", "aaa");
        } else {
            book.removeAttribute("data-climb-size");
        }
        store("cbb-size", size);
        $$("[data-cbb-size-select]").forEach(function (s) { s.value = size === "aaa" ? "aaa" : "standard"; });
    }
    $$("[data-cbb-theme-select]").forEach(function (s) {
        s.addEventListener("change", function () { setTheme(s.value); });
    });
    $$("[data-cbb-size-select]").forEach(function (s) {
        s.addEventListener("change", function () { setSize(s.value); });
    });
    $$("[data-cbb-set-theme]").forEach(function (b) {
        b.addEventListener("click", function () {
            setTheme(b.getAttribute("data-cbb-set-theme"));
            window.scrollTo({ top: 0, behavior: reduced.matches ? "auto" : "smooth" });
        });
    });

    // ---------------------------------------------------------------- colour page

    var copyFormat = "hex";
    $$("[data-cbb-copy-format]").forEach(function (b) {
        b.addEventListener("click", function () {
            copyFormat = b.getAttribute("data-cbb-copy-format");
            $$("[data-cbb-copy-format]").forEach(function (o) { o.setAttribute("aria-pressed", String(o === b)); });
        });
    });
    $$("[data-cbb-copy-hex]").forEach(function (b) {
        b.addEventListener("click", function () {
            var v = b.getAttribute("data-cbb-copy-" + copyFormat);
            if (!v) {
                // Only the core colours have print values; say so rather than copy nothing.
                say("No " + (copyFormat === "cmyk" ? "CMYK" : "Pantone") + " value for " + b.getAttribute("data-cbb-name"));
                return;
            }
            copy(v, v);
        });
    });

    var colours = [];
    try {
        colours = JSON.parse(($("#cbb-colours") || {}).textContent || "[]");
    } catch (e) { colours = []; }

    var checker = $("[data-cbb-checker]");
    if (checker) {
        var fg = $("[data-cbb-fg]", checker), bg = $("[data-cbb-bg]", checker);
        var seen = {};
        colours.forEach(function (c) {
            if (seen[c.hex]) {
                return;
            }
            seen[c.hex] = 1;
            [fg, bg].forEach(function (sel) {
                var o = document.createElement("option");
                o.value = c.hex;
                o.textContent = c.name + " " + c.hex;
                sel.appendChild(o);
            });
        });
        fg.value = "#E8712A";
        bg.value = "#1E0F05";
        var check = function () {
            var r = ratio(fg.value, bg.value);
            var sample = $("[data-cbb-sample]", checker);
            sample.style.color = fg.value;
            sample.style.background = bg.value;
            $("[data-cbb-ratio]", checker).textContent = r.toFixed(2);
            var grades = [
                ["Body text, AA", 4.5], ["Large text, AA", 3], ["Body text, AAA", 7], ["Large text, AAA", 4.5],
                ["Icons and marks", 3]
            ];
            $("[data-cbb-grades]", checker).innerHTML = grades.map(function (g) {
                var ok = r >= g[1];
                return '<li class="' + (ok ? "is-pass" : "is-fail") + '"><span>' + g[0] + " (" + g[1] + ':1)</span><b>' +
                    (ok ? "Pass" : "Fail") + "</b></li>";
            }).join("");
            var verdict;
            if (fg.value === bg.value) {
                verdict = "Pick two different colours.";
            } else if (r >= 7) {
                verdict = "Use it for any text, even in the AAA themes.";
            } else if (r >= 4.5) {
                verdict = "Use it for any text.";
            } else if (r >= 3) {
                verdict = "Large text only: 24px, or 19px bold. Fine for icons and marks.";
            } else {
                verdict = "Do not use this pair for text or for anything that carries meaning.";
            }
            $("[data-cbb-verdict]", checker).textContent = verdict;
        };
        fg.addEventListener("change", check);
        bg.addEventListener("change", check);
        $("[data-cbb-swap]", checker).addEventListener("click", function () {
            var t = fg.value;
            fg.value = bg.value;
            bg.value = t;
            check();
        });
        check();
    }

    // ---------------------------------------------------------------- headline builder

    var builder = $("[data-cbb-builder]");
    if (builder) {
        var input = $("[data-cbb-builder-text]", builder);
        var out = $("[data-cbb-builder-out]", builder);
        var wordsBox = $("[data-cbb-builder-words]", builder);
        var stage = $("[data-cbb-builder-stage]", builder);
        var ground = $("[data-cbb-builder-ground]", builder);
        var note = $("[data-cbb-builder-check]", builder);
        var GROUNDS = {
            "3": { bg: "#1E0F05", head: "#FFFFFF", acc: "#E8712A", eyebrow: "#F2AE86" },
            "5": { bg: "#242322", head: "#FFFFFF", acc: "#E8712A", eyebrow: "#F2AE86" },
            "1": { bg: "#FFFFFF", head: "#242322", acc: "#E8712A", eyebrow: "#8D4419" },
            "2": { bg: "#E9E9E9", head: "#242322", acc: "#D5641E", eyebrow: "#7A3B16" },
            "4": { bg: "#E8712A", head: "#FFFFFF", acc: "#FFFFFF", eyebrow: "#FFFFFF" }
        };
        var accent = -1, em = -1, words = [];
        var tokens = function () { return input.value.trim().split(/\s+/).filter(Boolean); };
        var pick = function () {
            words = tokens();
            var lower = words.map(function (w) { return w.toLowerCase().replace(/[^a-z0-9]/g, ""); });
            em = lower.indexOf("conference");
            accent = lower.indexOf("growth");
            if (em < 0) { em = Math.min(1, words.length - 1); }
            if (accent < 0 || accent === em) { accent = words.length - 1 === em ? 0 : words.length - 1; }
        };
        var markup = function (forCopy) {
            return words.map(function (w, i) {
                var t = esc(w);
                if (i === em) { t = "<em>" + t + "</em>"; }
                if (i === accent) { t = '<span class="climb-accent">' + t + "</span>"; }
                return t;
            }).join(" ");
        };
        var render = function () {
            var g = GROUNDS[ground.value];
            stage.style.setProperty("--b-bg", g.bg);
            stage.style.setProperty("--b-head", g.head);
            stage.style.setProperty("--b-acc", g.acc);
            stage.style.setProperty("--b-eyebrow", g.eyebrow);
            out.innerHTML = markup();
            wordsBox.innerHTML = "";
            words.forEach(function (w, i) {
                var b = document.createElement("button");
                b.type = "button";
                b.textContent = w;
                b.className = (i === accent ? "is-accent " : "") + (i === em ? "is-em" : "");
                b.setAttribute("aria-pressed", String(i === accent || i === em));
                b.addEventListener("click", function () {
                    var mode = ($('input[name="cbb-builder-mode"]:checked', builder) || {}).value;
                    if (mode === "em") {
                        em = em === i ? -1 : i;
                    } else {
                        accent = accent === i ? -1 : i;
                    }
                    render();
                    var again = wordsBox.children[i];
                    if (again) { again.focus(); }
                });
                wordsBox.appendChild(b);
            });
            var tips = [];
            var text = input.value;
            if (/[!\u2013\u2014]/.test(text)) { tips.push("No exclamation marks or dashes in ClimbUK copy."); }
            if (/\bclimb\b(?!uk|group|\d)/i.test(text)) { tips.push("Write ClimbUK, ClimbGroup or Climb27, never Climb on its own."); }
            if (text.length > 60) { tips.push("Keep display lines short: this one is " + text.length + " characters."); }
            if (accent < 0) { tips.push("Pick one word for Climb Orange."); }
            if (em < 0) { tips.push("Pick one word for italic."); }
            if (ground.value === "4" && accent >= 0) { tips.push("On Climb Orange there is no orange word: the italic word carries the line."); }
            note.textContent = tips.length ? tips.join(" ") : "On brand: one orange word, one italic word, short and loud.";
        };
        input.addEventListener("input", function () {
            var before = words.length;
            words = tokens();
            if (accent >= words.length) { accent = words.length - 1; }
            if (em >= words.length) { em = -1; }
            if (before === 0) { pick(); }
            render();
        });
        ground.addEventListener("change", render);
        $("[data-cbb-builder-copy]", builder).addEventListener("click", function () {
            copy('<h2 class="climb-display">' + markup() + "</h2>", "the headline HTML");
        });
        pick();
        render();
    }

    // ---------------------------------------------------------------- component frames

    function Frame(card) {
        var box = $("[data-cbb-frame]", card);
        var iframe = $("iframe", box);
        var widthSel = $("[data-cbb-width]", card);
        var themeSel = $("[data-cbb-comp-theme]", card);
        var native = parseInt(iframe.getAttribute("height"), 10) || 480;
        var loaded = false;
        var self = this;
        function theme() { return (themeSel && themeSel.value) || currentTheme(); }
        function fit() {
            var w = parseInt(widthSel.value, 10);
            var avail = box.clientWidth || card.clientWidth;
            var scale = Math.min(1, avail / w);
            iframe.style.width = w + "px";
            iframe.style.height = native + "px";
            iframe.style.transform = "translateX(-50%) scale(" + scale + ")";
            box.style.height = Math.ceil(native * scale) + "px";
            box.classList.toggle("is-narrow", w < avail - 40);
        }
        this.name = iframe.name;
        this.win = function () { return iframe.contentWindow; };
        this.load = function () {
            if (loaded) { return; }
            loaded = true;
hooks.frame(iframe, theme());
        };
        this.theme = function () {
            if (loaded && iframe.contentWindow) {
                iframe.contentWindow.postMessage({ cbbTheme: theme() }, "*");
            }
        };
        this.height = function (h) {
            if (h > 40 && Math.abs(h - native) > 2) {
                native = h;
                fit();
            }
        };
        widthSel.addEventListener("change", function () { fit(); });
        if (themeSel) { themeSel.addEventListener("change", function () { self.theme(); }); }
        var copyBtn = $("[data-cbb-copy-html]", card);
        var code = $("template[data-cbb-code]", card);
        if (copyBtn && code) {
            copyBtn.addEventListener("click", function () { copy(code.innerHTML.trim(), "the " + card.querySelector(".cbb-comp-name").textContent + " HTML"); });
        }
        if (window.ResizeObserver) {
            new ResizeObserver(fit).observe(box);
        }
        // On a phone, show the phone layout rather than a shrunken desktop one.
        if ((box.clientWidth || card.clientWidth) < 600) {
            widthSel.value = "390";
        }
        fit();
    }
    $$("[data-cbb-comp]").forEach(function (card) { frames.push(new Frame(card)); });
    if (frames.length) {
        if ("IntersectionObserver" in window) {
            var io = new IntersectionObserver(function (entries) {
                entries.forEach(function (e) {
                    if (e.isIntersecting) {
                        var f = frames.filter(function (x) { return x.card === e.target; })[0];
                        if (f) { f.load(); io.unobserve(e.target); }
                    }
                });
            }, { rootMargin: "600px 0px" });
            $$("[data-cbb-comp]").forEach(function (card, i) { frames[i].card = card; io.observe(card); });
        } else {
            frames.forEach(function (f) { f.load(); });
        }
        // Only the preview frames on this page may resize themselves.
        window.addEventListener("message", function (e) {
            if (e.origin !== window.location.origin || !e.data || !e.data.cbbFrame) { return; }
            frames.forEach(function (f) {
                if (f.name === e.data.cbbFrame && f.win() === e.source) { f.height(e.data.height); }
            });
        });
        var search = $("[data-cbb-comp-search]");
        if (search) {
            search.addEventListener("input", function () {
                var q = search.value.trim().toLowerCase();
                var shown = 0;
                $$("[data-cbb-comp]").forEach(function (card) {
                    var hit = !q || card.getAttribute("data-cbb-comp-search-text").indexOf(q) >= 0;
                    card.hidden = !hit;
                    shown += hit ? 1 : 0;
                    var link = $('[data-cbb-comp-link="' + card.getAttribute("data-cbb-comp") + '"]');
                    if (link) { link.hidden = !hit; }
                    if (hit) {
                        var f = frames.filter(function (x) { return x.card === card; })[0];
                        if (f && q) { f.load(); }
                    }
                });
                $$("[data-cbb-comp-group]").forEach(function (h) {
                    var g = h.getAttribute("data-cbb-comp-group");
                    h.hidden = !$$("[data-cbb-comp]").some(function (c) {
                        return !c.hidden && c.querySelector(".cbb-eyebrow").textContent === g;
                    });
                });
                $("[data-cbb-comp-empty]").hidden = shown > 0;
            });
        }
    }

    // ---------------------------------------------------------------- logo lab

    var lab = $("[data-cbb-lab]");
    if (lab) {
        var variants = JSON.parse(($("#cbb-logo-variants") || {}).textContent || "[]");
        var labStage = $("[data-cbb-lab-stage]", lab);
        var labLogo = $("[data-cbb-lab-logo]", lab);
        var labImg = $("[data-cbb-lab-img]", lab);
        var sizeIn = $("[data-cbb-lab-size]", lab);
        var sizeOut = $("[data-cbb-lab-size-out]", lab);
        var spaceIn = $("[data-cbb-lab-space]", lab);
        var verdictEl = $("[data-cbb-lab-verdict]", lab);
        var groundNames = { 1: "White", 2: "Light Grey", 3: "Dark Brown", 4: "Climb Orange", 5: "Charcoal", 6: "a dark photo" };
        var brands = ["ClimbUK", "ClimbGroup", "Climb27"];
        var update = function () {
            var picked = $('input[name="cbb-lab-brand"]:checked', lab).value;
            var brand = brands.filter(function (b) { return b === picked; })[0] || brands[0];
            var g = parseInt($('input[name="cbb-lab-ground"]:checked', lab).value, 10);
            var width = parseInt(sizeIn.value, 10);
            var small = width < 120;
            var choice = variants.filter(function (v) {
                var square = v[0].indexOf("icon") === 0;
                return v[2].indexOf(g) >= 0 && (small ? v[0] === "icon-monogram" : !square);
            })[0] || variants.filter(function (v) { return v[0] === "icon-monogram"; })[0];
            var square = choice[0].indexOf("icon") === 0;
            labStage.setAttribute("data-ground", g);
            labLogo.style.width = (square ? Math.min(width, 200) : width) + "px";
            labImg.setAttribute("src", hooks.asset("logos/" + encodeURIComponent(brand + "_" + choice[0] + ".svg")));
            labImg.alt = brand + " logo, " + choice[1].toLowerCase();
            sizeOut.textContent = width + "px";
            labLogo.classList.toggle("show-space", spaceIn.checked && !square);
            var msg = "On " + groundNames[g] + ", use " + choice[1].toLowerCase() + ". " + choice[3];
            if (small) {
                msg = "Below 120px wide, use the monogram. " + msg;
            } else if (g === 4) {
                msg += " On Climb Orange only the one-colour logo works.";
            }
            if (spaceIn.checked && square) {
                msg += " Clear space is measured on the wordmark.";
            }
            verdictEl.textContent = msg;
            requestAnimationFrame(function () {
                labLogo.style.setProperty("--cbb-space", Math.round(labImg.getBoundingClientRect().height) + "px");
            });
        };
        $$("input", lab).forEach(function (i) { i.addEventListener("input", update); i.addEventListener("change", update); });
        labImg.addEventListener("load", function () {
            labLogo.style.setProperty("--cbb-space", Math.round(labImg.getBoundingClientRect().height) + "px");
        });
        update();
    }

    // ---------------------------------------------------------------- motion

    var reducedNote = $("[data-cbb-reduced]");
    if (reducedNote) { reducedNote.hidden = !reduced.matches; }
    $$("[data-cbb-curve]").forEach(function (card) {
        var value = card.getAttribute("data-cbb-curve");
        var m = /cubic-bezier\(([^)]+)\)/.exec(value);
        var p = m ? m[1].split(",").map(parseFloat) : [0, 0, 1, 1];
        var svg = $("[data-cbb-curve-graph]", card);
        var X = function (v) { return v * 100; }, Y = function (v) { return 100 - v * 100; };
        svg.innerHTML = '<path class="axis" d="M0 0V100H100"/><path class="axis" d="M0 0H100" stroke-dasharray="4 4"/>' +
            '<path class="line" d="M' + X(0) + " " + Y(0) + "C" + X(p[0]) + " " + Y(p[1]) + " " + X(p[2]) + " " + Y(p[3]) +
            " " + X(1) + " " + Y(1) + '"/>';
        card.setAttribute("data-easing", value);
    });
    $$("[data-cbb-play]").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var host = btn.closest("[data-cbb-curve]") || btn.closest("li");
            var ball = $("[data-cbb-ball]", host);
            var easing = host.getAttribute("data-easing") || "var(--climb-motion-easing-standard)";
            var duration = ball.getAttribute("data-cbb-duration") || "var(--climb-motion-duration-stage)";
            var end = !ball.classList.contains("is-end");
            if (reduced.matches) {
                ball.style.transition = "opacity var(--climb-motion-duration-quick) linear";
                ball.style.opacity = "0";
                setTimeout(function () {
                    ball.classList.toggle("is-end", end);
                    ball.style.opacity = "1";
                }, 160);
                return;
            }
            ball.style.transition = "left " + duration + " " + easing;
            ball.classList.toggle("is-end", end);
        });
    });
    $$("[data-cbb-replay-btn]").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var el = $("[data-cbb-replay]", btn.closest(".cbb-move"));
            el.classList.remove("is-playing");
            void el.offsetWidth;
            el.classList.add("is-playing");
        });
    });

    // ---------------------------------------------------------------- breakpoints

    var bp = $("[data-cbb-bp]");
    if (bp) {
        var steps = $$("[data-cbb-bp-min]", bp);
        var marker = $("[data-cbb-bp-marker]", bp);
        var vw = $("[data-cbb-viewport]"), name = $("[data-cbb-breakpoint]");
        var place = function () {
            var w = window.innerWidth, current = null;
            steps.forEach(function (s) {
                var on = w >= parseInt(s.getAttribute("data-cbb-bp-min"), 10);
                s.classList.toggle("is-on", on);
                if (on) { current = s; }
            });
            vw.textContent = w + "px";
            name.textContent = current ? current.querySelector("b").textContent : "xs";
            var max = 1600, x = Math.min(w, max) / max;
            marker.style.left = "calc(" + (x * 100) + "% - 10px)";
        };
        window.addEventListener("resize", place);
        place();
    }

    // ---------------------------------------------------------------- menu and view bar

    var nav = $("[data-cbb-nav]");
    var menuBtns = $$("[data-cbb-menu-btn]");
    function closeMenus(except) {
        menuBtns.forEach(function (b) {
            if (b !== except) {
                b.setAttribute("aria-expanded", "false");
                document.getElementById(b.getAttribute("aria-controls")).hidden = true;
            }
        });
    }
    menuBtns.forEach(function (b) {
        b.addEventListener("click", function () {
            var open = b.getAttribute("aria-expanded") !== "true";
            closeMenus(b);
            b.setAttribute("aria-expanded", String(open));
            document.getElementById(b.getAttribute("aria-controls")).hidden = !open;
        });
    });
    // Menu and View collapse the bar at phone width; on wider screens both stay open and the buttons hide.
    $$("[data-cbb-toggle]").forEach(function (b) {
        var panel = document.getElementById(b.getAttribute("data-cbb-toggle"));
        b.addEventListener("click", function () {
            var open = b.getAttribute("aria-expanded") !== "true";
            b.setAttribute("aria-expanded", String(open));
            panel.classList.toggle("is-open", open);
            if (!open) { closeMenus(); }
        });
    });
    if (nav) {
        document.addEventListener("click", function (e) {
            if (!e.target.closest(".cbb-menu-group")) { closeMenus(); }
            if (!e.target.closest("[data-cbb-search-box]")) { hideSearch(); }
        });
        nav.addEventListener("keydown", function (e) {
            if (e.key !== "Escape") {
                return;
            }
            var open = menuBtns.filter(function (b) { return b.getAttribute("aria-expanded") === "true"; })[0];
            if (open) {
                closeMenus();
                open.focus();
            }
            hideSearch();
        });
        nav.addEventListener("focusout", function (e) {
            if (e.relatedTarget && !e.relatedTarget.closest(".cbb-menu-group")) { closeMenus(); }
        });
    }

    // The bar sticks under the website's own header while that header is on screen, and to the top otherwise. Site
    // headers can be fixed, slide away or fade out on scroll, so the bar follows the header's visible edge for the
    // length of its animation rather than only on the scroll event that started it.
    var siteHeader = document.querySelector("header#top");
    function headerEdge() {
        if (!siteHeader) {
            return 0;
        }
        var s = window.getComputedStyle(siteHeader);
        if ((s.position !== "fixed" && s.position !== "sticky") || s.visibility === "hidden" ||
                parseFloat(s.opacity) < 0.5) {
            return 0;
        }
        return Math.max(0, Math.round(siteHeader.getBoundingClientRect().bottom));
    }
    function stickTop() {
        book.style.setProperty("--cbb-stick", headerEdge() + "px");
        // Sidebars and jump targets sit below the bar, whatever its height (it grows when View opens on a phone).
        if (nav) { book.style.setProperty("--cbb-bar", nav.offsetHeight + "px"); }
    }
    var followUntil = 0, following = false;
    function follow() {
        stickTop();
        if (window.performance.now() < followUntil) {
            window.requestAnimationFrame(follow);
        } else {
            following = false;
        }
    }
    var settleTimer;
    function queueStick() {
        // A last measure once things have settled, in case animation frames were skipped (a background tab).
        clearTimeout(settleTimer);
        settleTimer = setTimeout(stickTop, 900);
        followUntil = window.performance.now() + 700;
        if (!following) {
            following = true;
            window.requestAnimationFrame(follow);
        }
    }
    document.addEventListener("scroll", queueStick, { capture: true, passive: true });
    window.addEventListener("resize", queueStick);
    if (siteHeader) {
        siteHeader.addEventListener("transitionend", queueStick);
        siteHeader.addEventListener("transitioncancel", queueStick);
        if (window.ResizeObserver) { new ResizeObserver(queueStick).observe(siteHeader); }
    }
    if (nav && window.ResizeObserver) { new ResizeObserver(queueStick).observe(nav); }
    stickTop();

    // ---------------------------------------------------------------- media kit: brand, archive, previews

    var FORMAT_KEY = "climbMediaKitFormat";
    var LABELS = { zip: "ZIP", "7z": "7Z", "tar.gz": "TAR.GZ", "tar.xz": "TAR.XZ", "tar.bz2": "TAR.BZ2" };
    var totals = {};
    try {
        totals = JSON.parse(($("#cbb-kit-totals") || {}).textContent || "{}");
    } catch (e) { totals = {}; }
    function humanSize(bytes) {
        if (!bytes) {
            return "";
        }
        var units = ["bytes", "KB", "MB", "GB"], n = bytes, i = 0;
        while (n >= 1000 && i < units.length - 1) { n /= 1000; i++; }
        return i < 2 ? Math.round(n) + " " + units[i] : n.toFixed(1) + " " + units[i];
    }
    var brandSel = $("[data-cbb-brand-select]"), formatSel = $("[data-cbb-format-select]");
    var groundSel = $("[data-cbb-ground-select]");
    var cards = $$(".cbb-kit-card");
    var queryBrand = new URLSearchParams(window.location.search).get("brand");
    var kit = {
        brand: queryBrand || store("cbb-brand") || "all",
        format: store(FORMAT_KEY) || "zip",
        ground: store("cbb-ground") || "auto",
        words: [],
    };
    if (brandSel && !$('option[value="' + kit.brand + '"]', brandSel)) { kit.brand = "all"; }
    if (formatSel && !$('option[value="' + kit.format + '"]', formatSel)) { kit.format = formatSel.options.length ? formatSel.options[0].value : "zip"; }
    $$("[data-cbb-kit-only]").forEach(function (el) { el.hidden = !cards.length; });

    function applyKit(announce) {
        var shown = 0;
        $$("[data-cbb-kit-grid]").forEach(function (grid) {
            var n = 0;
            $$(".cbb-kit-card", grid).forEach(function (card) {
                var b = card.getAttribute("data-brand");
                var text = card.getAttribute("data-search") || "";
                var ok = (kit.brand === "all" || b === kit.brand || b === "shared") &&
                    kit.words.every(function (w) { return text.indexOf(w) >= 0; });
                card.hidden = !ok;
                if (ok) { n++; }
            });
            var empty = grid.nextElementSibling;
            if (empty && empty.hasAttribute("data-cbb-kit-empty")) { empty.hidden = n > 0; }
            shown += n;
        });
        var label = LABELS[kit.format] || kit.format.toUpperCase();
        var per = totals[kit.brand] || totals.all || {};
        $$("[data-cbb-bundle]").forEach(function (a) {
            var cat = a.getAttribute("data-cbb-category");
            var q = new URLSearchParams({ format: kit.format });
            if (kit.brand !== "all") { q.set("brand", kit.brand); }
            if (cat) { q.set("category", cat); }
            a.setAttribute("href", "/media-kit/download?" + q);
            var t = per[cat || "all"] || { count: 0, size: 0 };
            var tag = $("[data-cbb-format-label]", a);
            if (tag) { tag.textContent = t.size && !a.hasAttribute("data-cbb-no-size") ? label + ", " + humanSize(t.size) : label; }
            var row = a.closest("[data-cbb-kit-row]");
            if (row && $("[data-cbb-row-size]", row) && totals.all) {
                $("[data-cbb-row-size]", row).textContent = t.count + (t.count === 1 ? " file, " : " files, ") + humanSize(t.size);
            }
            a.classList.toggle("is-disabled", !!totals.all && !t.count);
            if (totals.all && !t.count) { a.setAttribute("aria-disabled", "true"); } else { a.removeAttribute("aria-disabled"); }
        });
        $$("[data-cbb-variant]").forEach(function (a) {
            a.setAttribute("href", "/media-kit/download?" + new URLSearchParams({ format: kit.format, variant: a.getAttribute("data-cbb-variant") }));
            var tag = $("[data-cbb-format-label]", a);
            if (tag) { tag.textContent = label; }
        });
        var all = per.all || { count: 0, size: 0 };
        $$("[data-cbb-bundle-size]").forEach(function (el) {
            if (all.count) { el.textContent = all.count + " files, " + humanSize(all.size) + " before compression"; }
        });
        if (kit.ground === "auto") { book.removeAttribute("data-cbb-ground"); } else { book.setAttribute("data-cbb-ground", kit.ground); }
        if (brandSel) { brandSel.value = kit.brand; }
        if (formatSel) { formatSel.value = kit.format; }
        if (groundSel) { groundSel.value = kit.ground; }
        if (announce && cards.length) {
            say(shown === 1 ? "Showing 1 design" : "Showing " + shown + " designs");
        }
    }
    if (brandSel) {
        brandSel.addEventListener("change", function () {
            kit.brand = brandSel.value;
            store("cbb-brand", kit.brand);
            if (queryBrand) {
                // The brand in the address came from an old media kit link; the menu choice replaces it.
                queryBrand = null;
                window.history.replaceState(null, "", hooks.withoutBrand());
            }
            applyKit(true);
        });
    }
    if (formatSel) {
        formatSel.addEventListener("change", function () { kit.format = formatSel.value; store(FORMAT_KEY, kit.format); applyKit(); });
    }
    if (groundSel) {
        groundSel.addEventListener("change", function () { kit.ground = groundSel.value; store("cbb-ground", kit.ground); applyKit(); });
    }

    // ---------------------------------------------------------------- search

    var searchBox = $("[data-cbb-search-box]");
    var searchIn = $("[data-cbb-search]"), panel = $("[data-cbb-search-panel]");
    var index = null, loading = null;
    function hideSearch() {
        if (panel) { panel.hidden = true; }
    }
    function loadIndex() {
        if (!loading) {
            loading = window.fetch(searchBox.getAttribute("data-cbb-search-src"), { credentials: "same-origin" })
                .then(function (r) { return r.ok ? r.json() : { pages: [], files: [] }; })
                .catch(function () { return { pages: [], files: [] }; })
                .then(function (d) { index = d; return d; });
        }
        return loading;
    }
    function hit(item, words) {
        var text = (item.search || (item.title + " " + (item.text || "") + " " + item.kind)).toLowerCase();
        return words.every(function (w) { return text.indexOf(w) >= 0; });
    }
    function showResults() {
        var words = kit.words;
        if (!words.length) {
            hideSearch();
            return;
        }
        var list = $("[data-cbb-search-list]", panel), count = $("[data-cbb-search-count]", panel);
        var pages = (index ? index.pages : []).filter(function (p) { return hit(p, words); });
        var files = (index ? index.files : []).filter(function (f) {
            return (kit.brand === "all" || f.brand === kit.brand || f.brand === "shared") && hit(f, words);
        });
        var here = window.location.pathname;
        var rows = pages.slice(0, 6).concat(files.slice(0, 14)).map(function (r) {
            var img = r.preview ? '<img src="' + esc(hooks.asset(r.preview)) + '" alt="" loading="lazy">' : '<span class="cbb-search-kind" aria-hidden="true"></span>';
            var on = r.url.split("#")[0] === here ? " (this page)" : "";
            return '<li><a href="' + esc(hooks.link(r.url)) + '">' + img + "<span><b>" + esc(r.title) + "</b><small>" + esc(r.kind) + on + "</small></span></a></li>";
        });
        var total = pages.length + files.length;
        count.textContent = !index ? "Searching" : total ? total + (total === 1 ? " result" : " results") +
            (total > rows.length ? ", showing the first " + rows.length : "") : "Nothing found. Try logo, rocket or banner.";
        list.innerHTML = rows.join("");
        panel.hidden = false;
    }
    if (searchIn && panel) {
        searchIn.addEventListener("input", function () {
            kit.words = searchIn.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
            applyKit();
            showResults();
            if (!index) { loadIndex().then(showResults); }
        });
        searchIn.addEventListener("focus", function () { loadIndex(); if (kit.words.length) { showResults(); } });
        searchIn.addEventListener("keydown", function (e) {
            if (e.key === "ArrowDown" || e.key === "Enter") {
                var first = $("a", panel);
                if (first && !panel.hidden) {
                    e.preventDefault();
                    if (e.key === "Enter") { first.click(); } else { first.focus(); }
                }
            }
        });
        panel.addEventListener("keydown", function (e) {
            var links = $$("a", panel), i = links.indexOf(document.activeElement);
            if (e.key === "ArrowDown" && i < links.length - 1) { e.preventDefault(); links[i + 1].focus(); }
            if (e.key === "ArrowUp") { e.preventDefault(); (i > 0 ? links[i - 1] : searchIn).focus(); }
        });
    }

    // ---------------------------------------------------------------- start

    applyKit();
    setSize(store("cbb-size") || "standard");
    setTheme(store("cbb-theme") || "dark", true);
}
